/* App shell only; no Firebase user data or API responses cached. */
const CACHE='english-adventure-shell-v5';
const SHELL=['/','/index.html','/style.css','/app.js','/manifest.webmanifest','/icons/icon.svg','/icons/icon-192.png','/icons/icon-512.png','/art/city.svg','/art/listen.svg','/art/read.svg','/art/write.svg','/art/speak.svg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('english-adventure-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET'||new URL(req.url).origin!==self.location.origin)return;const url=new URL(req.url);if(url.pathname.startsWith('/__/')||url.pathname.startsWith('/api/')||url.pathname.startsWith('/firebase'))return;event.respondWith(fetch(req).then(response=>{if(response.ok&&response.type==='basic'&&(SHELL.includes(url.pathname)||url.pathname==='/')){const copy=response.clone();caches.open(CACHE).then(c=>c.put(req,copy))}return response}).catch(()=>caches.match(req).then(cached=>cached||((req.mode==='navigate')?caches.match('/index.html'):Response.error()))))});
